import Foundation

struct Word: Codable, Hashable {
    let id: String
    let word: String
    let reading: String
    let meaning: String
    /// Shortest example sentence for the word.
    let example: String

    /// True when the word is written in kana only, so the reading line would just repeat it.
    var isKanaOnly: Bool { word == reading }
}

enum Words {
    /// All Kasane vocab in a fixed shuffled order (generated by scripts/widget-words.mjs).
    static let all: [Word] = {
        guard let url = Bundle.main.url(forResource: "words", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let words = try? JSONDecoder().decode([Word].self, from: data),
              !words.isEmpty
        else { return [Word(id: "none", word: "重ね", reading: "かさね", meaning: "layers", example: "")] }
        return words
    }()

    /// The word for the hour containing `date`. Hour by hour it walks the whole list, so every
    /// word shows once per cycle (705 words ≈ 29 days) before any repeats.
    static func word(at date: Date) -> Word {
        let hour = Int(floor(date.timeIntervalSince1970 / 3600))
        return all[((hour % all.count) + all.count) % all.count]
    }

    /// Start of the hour containing `date`.
    static func hourStart(_ date: Date) -> Date {
        Date(timeIntervalSince1970: floor(date.timeIntervalSince1970 / 3600) * 3600)
    }
}
